CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_seed_dummy_senha_fila_500`()
BEGIN

    DECLARE v_i INT DEFAULT 1;

    START TRANSACTION;

    WHILE v_i <= 500 DO

        INSERT INTO senha
        (
            numero,
            prefixo,
            status,
            ativo,
            criado_em
        )
        VALUES
        (
            v_i,
            'TMP',
            'AGUARDANDO',
            1,
            NOW(6)
        )
        ON DUPLICATE KEY UPDATE
            numero = VALUES(numero);

        SET v_i = v_i + 1;

    END WHILE;

    COMMIT;

END ;;
